-- Production PostgreSQL target additions for workflow/task/audit/creative domains.
CREATE TABLE IF NOT EXISTS workflow_tasks(id uuid PRIMARY KEY,user_id uuid NOT NULL,task_key text NOT NULL,title text NOT NULL,category text NOT NULL,status text NOT NULL,priority text NOT NULL,trigger_name text NOT NULL,completion_mode text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz);
CREATE INDEX IF NOT EXISTS idx_workflow_tasks_user_status ON workflow_tasks(user_id,status,created_at DESC);
CREATE TABLE IF NOT EXISTS onboarding_states(id uuid PRIMARY KEY,user_id uuid NOT NULL UNIQUE,kind text NOT NULL,status text NOT NULL,current_step text NOT NULL,progress integer NOT NULL DEFAULT 0,data jsonb NOT NULL DEFAULT '{}'::jsonb,submitted_at timestamptz,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS gig_drafts(id uuid PRIMARY KEY,user_id uuid NOT NULL,status text NOT NULL DEFAULT 'DRAFT',payload jsonb NOT NULL,compliance_preflight jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS compliance_queue(id uuid PRIMARY KEY,user_id uuid NOT NULL,resource_type text NOT NULL,resource_id uuid,status text NOT NULL DEFAULT 'PENDING',preflight jsonb,created_at timestamptz NOT NULL DEFAULT now(),reviewed_at timestamptz);
CREATE TABLE IF NOT EXISTS creative_assets(id uuid PRIMARY KEY,user_id uuid NOT NULL,mode text NOT NULL,storage_key text NOT NULL,label text NOT NULL DEFAULT 'AI_ASSISTED',prompt text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS creative_projects(id uuid PRIMARY KEY,user_id uuid NOT NULL,name text NOT NULL,headline text,subheadline text,cta text,format text,asset_key text,status text NOT NULL DEFAULT 'DRAFT',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS product_projects(id uuid PRIMARY KEY,user_id uuid NOT NULL,product_type text NOT NULL,service text NOT NULL,plan text NOT NULL,label text NOT NULL DEFAULT 'AI_ASSISTED_PRODUCT_DRAFT',created_at timestamptz NOT NULL DEFAULT now());